    let idx = 0;
    let used = [];
    for (let i = 0; i < 8; i++) {
        used.push(new Array(8).fill(0));
    }
    let v = [];
    for (let i = 0; i < 8; i++) {
        let str = data[idx++].trim();
        ar.push(str);
        for (let j = 0; j < 8; j++) {
            if (str[j] === 'S') {
                v.push([i, j]);
            }
        }
    }

    let x = 0;
    x = dfs(7, 0, v, used);
    if (x === 1) { console.log("WIN"); return; }
