    x = dfs(6, 1, v, used);
    if (x === 1) { console.log("WIN"); return; }
    x = dfs(7, 1, v, used);
    if (x === 1) { console.log("WIN"); return; }
    else {
        console.log("LOSE");
    }
}

main();
